// The server sends timestamps as raw instants. Everything here works in the
// viewer's own timezone, which is the browser's, and words them the way the
// app does: "1:42 PM", "yesterday", "5 days ago", "Sep 12", "tomorrow", "in 3 days".

const MS_PER_DAY = 24 * 60 * 60 * 1000

// "5 days ago" and "in 5 days" are spelled out up to this many days away; further out, dates are shown instead.
const SPELLED_OUT_DAYS = 6

export function formatTime(date, format = "relative", now = new Date()) {
  switch (format) {
    case "time":
      return formatClock(date)
    case "date":
      return formatShortDate(date, now)
    case "day":
      return formatWeekdayDate(date)
    case "date_time":
      return formatDateTime(date)
    default:
      return formatRelative(date, now)
  }
}

export function signedDifferenceInDays(fromDate, toDate) {
  return calendarDayNumber(toDate) - calendarDayNumber(fromDate)
}

// Bridge descriptions are HTML snippets whose <time> elements carry raw
// timestamps. Returns the snippet as plain text, with each time formatted for the viewer.
export function textWithLocalTimes(html) {
  if (!html) return html

  const template = document.createElement("template")
  template.innerHTML = html

  template.content.querySelectorAll("time").forEach((time) => {
    time.textContent = formatTime(new Date(time.dateTime), time.dataset.localTimeFormatValue)
  })

  return template.content.textContent
}

function formatRelative(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return date > now ? `today at ${formatClock(date)}` : formatClock(date)
  } else if (days === -1) {
    return "yesterday"
  } else if (days < 0 && days >= -SPELLED_OUT_DAYS) {
    return `${-days} days ago`
  } else if (days === 1) {
    return "tomorrow"
  } else if (days > 1) {
    return `in ${days} days`
  } else {
    return formatShortDate(date, now)
  }
}

function formatClock(date) {
  return formatWith(date, { hour: "numeric", minute: "2-digit" })
}

function formatShortDate(date, now) {
  const sameYear = dateParts(date).year === dateParts(now).year

  return formatWith(date, { month: "short", day: "numeric", year: sameYear ? undefined : "numeric" })
}

function formatWeekdayDate(date) {
  return formatWith(date, { weekday: "long", month: "long", day: "numeric" })
}

function formatDateTime(date) {
  return formatWith(date, { dateStyle: "short", timeStyle: "short" })
}

function formatWith(date, options) {
  // Some engines put a narrow no-break space before AM/PM; the server never did.
  return new Intl.DateTimeFormat("en-US", options).format(date).replace(/[\u00a0\u202f]/g, " ")
}

// Day numbers count calendar days in the viewer's timezone, so differences are whole days across DST changes.
function calendarDayNumber(date) {
  const { year, month, day } = dateParts(date)

  return Date.UTC(year, month - 1, day) / MS_PER_DAY
}

function dateParts(date) {
  const parts = {}

  for (const { type, value } of new Intl.DateTimeFormat("en-US", { year: "numeric", month: "numeric", day: "numeric" }).formatToParts(date)) {
    if (type !== "literal") parts[type] = parseInt(value, 10)
  }

  return parts
}
