const MS_PER_DAY = 24 * 60 * 60 * 1000

// "5 days ago" and "in 5 days" are spelled out up to this many days away; further out, dates are shown instead.
const SPELLED_OUT_DAYS = 6

export function formatTime(date, format = "relative", now = new Date()) {
  switch (format) {
    case "time":
      return formatClock(date)
    case "date":
      return formatShortDate(date, now)
    case "day":
      return formatWeekdayDate(date)
    case "date_time":
      return formatDateTime(date)
    default:
      return formatRelative(date, now)
  }
}

export function signedDifferenceInDays(fromDate, toDate) {
  return calendarDayNumber(toDate) - calendarDayNumber(fromDate)
}

// Bridge descriptions are HTML snippets whose <time> elements carry raw
// timestamps. Returns the snippet as plain text, with each time formatted for the viewer.
export function textWithLocalTimes(html) {
  if (!html) return html

  const template = document.createElement("template")
  template.innerHTML = html

  template.content.querySelectorAll("time").forEach((time) => {
    time.textContent = formatTime(new Date(time.dateTime), time.dataset.localTimeFormatValue)
  })

  return template.content.textContent
}

function formatRelative(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
