  } else if (days === -1) {
    return "yesterday"
  } else if (days < 0 && days >= -SPELLED_OUT_DAYS) {
    return `${-days} days ago`
  } else if (days === 1) {
    return "tomorrow"
  } else if (days > 1) {
    return `in ${days} days`
